import av,numpy as np,math
path='/workspace/materials/flight.mp4';c=av.open(path);st=c.streams.video[0]
res=.5; angs=np.arange(0,360,res);rs=np.arange(16,38,.5)
maskang=np.array([not (a<18 or a>342 or 65<a<112) for a in angs])
def frame(t0):
 c.seek(int(t0/float(st.time_base)),stream=st,backward=True)
 for f in c.decode(video=0):
  if float(f.time)>=t0:return f.to_ndarray(format='rgb24')
def polar(im):
 g=np.min(im,axis=2).astype(float);out=np.empty((len(angs),len(rs)))
 for i,a in enumerate(angs):
  th=math.radians(a);xs=np.rint(626+rs*np.sin(th)).astype(int);ys=np.rint(506-rs*np.cos(th)).astype(int);out[i]=g[ys,xs]
 return out
def sh(p,q):
 # current p vs prev q; candidate shift current texture relative to prev
 vals=[]
 for k in range(-8,9):
  qq=np.roll(q,k,axis=0)
  # robust on outer; normalize global
  d=(p[maskang]-qq[maskang])
  vals.append(np.mean(np.minimum(d*d,2500)))
 k=np.argmin(vals)-8
 return k*res, vals
for start,end in [(15,60),(170,215),(360,420),(485,530),(600,645),(859,910),(1045,1095),(1220,1270),(1340,1390)]:
 ps=None;cum=0;arr=[]
 for t in np.arange(start,end+.01,.5):
  p=polar(frame(float(t)))
  if ps is not None:
   z,_=sh(p,ps);cum+=z;arr.append(z)
  ps=p
 print(start,end,'cum',cum,'nonzero',[(i+1,round(x,1)) for i,x in enumerate(arr) if x])
